<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'; import { api } from '../services/api'; import { socket } from '../services/socket'; import type { PartyEvent } from '../types';
const events=ref<PartyEvent[]>([]); async function refresh(){events.value=await api.getEvents();}
onMounted(()=>{refresh();socket.on('events:changed',refresh)}); onUnmounted(()=>socket.off('events:changed',refresh));
</script>
<template><main class="display-page"><header class="display-header"><div class="brand">PARTY<span>CASINO</span></div><div class="live-indicator"><i></i> PARTY LIVE</div></header><section class="display-intro"><p class="eyebrow">A KÖZÖS JÁTÉKTÉR</p><h1>Mi történik <span>most?</span></h1><p>Csatlakozz a telefonoddal a meghirdetett eseményekhez.</p></section><section v-if="events.length" class="display-events"><article v-for="event in events" :key="event.id" class="display-event" :class="event.status.toLowerCase()"><div class="display-event-info"><span class="status" :class="event.status.toLowerCase()">{{ event.status==='OPEN'?'CSATLAKOZÁS NYITVA':event.status==='RUNNING'?'ÉLŐ ESEMÉNY':'LEZÁRVA' }}</span><h2>{{ event.title }}</h2><p>{{ event.description }}</p></div><div class="display-count"><strong>{{ event.participantCount }}</strong><span>RÉSZTVEVŐ</span><div class="avatar-row"><span v-for="p in event.participants.slice(0,5)" :key="p.id">{{ p.name.slice(0,1).toUpperCase() }}</span></div><small>{{ event.participants.map(p=>p.name).join(' · ') }}</small><a v-if="event.eventType==='ROULETTE' && event.status==='RUNNING'" :href="'/roulette/' + event.id + '?display=1'" class="ghost">Rulett TV ↗</a></div></article></section><div v-else class="display-empty"><div>✳</div><h2>Hamarosan kezdődik a buli</h2><p>Az események itt fognak megjelenni.</p></div><footer><span>NYISD MEG A PARTY CASINO OLDALÁT A TELEFONODON</span><strong>VÁLASSZ ESEMÉNYT. CSATLAKOZZ. JÁTSSZATOK.</strong></footer></main></template>
